import sys
from tenacity import RetryCallState, Retrying, wait_exponential

class MockFuture:
    failed = True
    def exception(self):
        return Exception("fail")

def test_bug():
    wait_fn = wait_exponential(max=60)
    state = RetryCallState(Retrying(), None, (), {})
    state.attempt_number = 1000000
    # This should return max (60) quickly instead of doing 2^999999 calculation
    val = wait_fn(state)
    assert val == 60
